<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CMS - C-Net Library</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0;color:#1f2937}.wrap{max-width:1250px;margin:28px auto;padding:0 18px}.top,.inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;margin-bottom:18px}.grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px;margin-bottom:18px}.field{margin-bottom:10px}input,textarea{width:100%;padding:9px;border:1px solid #d1d5db;border-radius:8px;margin-top:4px}.btn{border:0;border-radius:8px;padding:9px 12px;background:#111827;color:#fff;text-decoration:none;cursor:pointer;font-weight:700}.alt{background:#0f766e}.danger{background:#b91c1c}.muted{color:#6b7280;font-size:12px}.item{border:1px solid #e5e7eb;border-radius:10px;padding:12px;margin-top:10px}.gallery{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.gallery img{width:100%;height:120px;object-fit:cover;border-radius:8px}.notice{padding:10px;border-radius:9px;margin-bottom:12px}.ok{background:#f0fdf4}.err{background:#fef2f2}@media(max-width:900px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><h1 style="margin:0">Website CMS</h1><div class="muted">Manage public pages, SEO, FAQs, testimonials and gallery.</div></div><div class="inline"><a class="btn alt" href="{{ route('home') }}" target="_blank">View Website</a><a class="btn" href="{{ route('admin.dashboard') }}">Dashboard</a></div></div>@if(session('success'))<div class="notice ok">{{ session('success') }}</div>@endif @if($errors->any())<div class="notice err"><ul style="margin:0;padding-left:18px">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<div class="grid"><div>@foreach($pages as $page)<div class="card"><h2 style="margin-top:0">{{ $page->title }} <span class="muted">/{{ $page->slug }}</span></h2><form method="POST" action="{{ route('admin.cms.pages.update',$page) }}">@csrf @method('PATCH')<div class="field"><label>Page Title<input name="title" value="{{ $page->title }}" required></label></div><div class="field"><label>Excerpt<textarea name="excerpt">{{ $page->excerpt }}</textarea></label></div><div class="field"><label>Content<textarea name="content" rows="9">{{ $page->content }}</textarea></label></div><div class="field"><label>SEO Title<input name="meta_title" value="{{ $page->meta_title }}"></label></div><div class="field"><label>SEO Description<textarea name="meta_description">{{ $page->meta_description }}</textarea></label></div><div class="field"><label>SEO Keywords<input name="meta_keywords" value="{{ $page->meta_keywords }}"></label></div><div class="field"><label>Canonical URL<input type="url" name="canonical_url" value="{{ $page->canonical_url }}"></label></div><label><input style="width:auto" type="checkbox" name="status" value="1" @checked($page->status)> Published</label><br><button class="btn alt" style="margin-top:8px">Save Page</button></form></div>@endforeach</div><div><div class="card"><h2 style="margin-top:0">Gallery</h2><form method="POST" enctype="multipart/form-data" action="{{ route('admin.cms.gallery.store') }}">@csrf<div class="field"><label>Title<input name="title"></label></div><div class="field"><label>Alt text<input name="alt_text"></label></div><div class="field"><label>Image<input type="file" name="image" accept="image/*" required></label></div><button class="btn alt">Upload Image</button></form>@if($galleryItems->isNotEmpty())<div class="gallery" style="margin-top:14px">@foreach($galleryItems as $item)<div><img src="{{ asset('storage/'.$item->image_path) }}" alt="{{ $item->alt_text }}"><div class="muted">{{ $item->title ?: 'Gallery image' }}</div><form method="POST" action="{{ route('admin.cms.gallery.destroy',$item) }}">@csrf @method('DELETE')<button class="btn danger" style="margin-top:5px">Remove</button></form></div>@endforeach</div>@endif</div><div class="card"><h2 style="margin-top:0">FAQ Management</h2><form method="POST" action="{{ route('admin.cms.faqs.store') }}">@csrf<div class="field"><label>Question<input name="question" required></label></div><div class="field"><label>Answer<textarea name="answer" required></textarea></label></div><button class="btn alt">Add FAQ</button></form>@foreach($faqs as $faq)<div class="item"><form method="POST" action="{{ route('admin.cms.faqs.update',$faq) }}">@csrf @method('PATCH')<input name="question" value="{{ $faq->question }}" required><textarea name="answer" rows="3" required>{{ $faq->answer }}</textarea><div class="inline"><label><input style="width:auto" type="checkbox" name="status" value="1" @checked($faq->status)> Published</label><button class="btn alt">Save Edit</button></div></form><form method="POST" action="{{ route('admin.cms.faqs.destroy',$faq) }}" style="margin-top:7px" onsubmit="return confirm('Delete this FAQ?')">@csrf @method('DELETE')<button class="btn danger">Delete FAQ</button></form></div>@endforeach</div><div class="card"><h2 style="margin-top:0">Testimonial Management</h2><form method="POST" action="{{ route('admin.cms.testimonials.store') }}">@csrf<div class="field"><label>Name<input name="name" required></label></div><div class="field"><label>Designation<input name="designation"></label></div><div class="field"><label>Message<textarea name="message" required></textarea></label></div><div class="field"><label>Rating<input type="number" min="1" max="5" name="rating" value="5"></label></div><button class="btn alt">Add Testimonial</button></form>@foreach($testimonials as $item)<div class="item"><form method="POST" action="{{ route('admin.cms.testimonials.update',$item) }}">@csrf @method('PATCH')<input name="name" value="{{ $item->name }}" required><input name="designation" value="{{ $item->designation }}" placeholder="Designation"><textarea name="message" rows="3" required>{{ $item->message }}</textarea><input type="number" min="1" max="5" name="rating" value="{{ $item->rating }}" required><div class="inline"><label><input style="width:auto" type="checkbox" name="status" value="1" @checked($item->status)> Published</label><button class="btn alt">Save Edit</button></div></form><form method="POST" action="{{ route('admin.cms.testimonials.destroy',$item) }}" style="margin-top:7px" onsubmit="return confirm('Delete this testimonial?')">@csrf @method('DELETE')<button class="btn danger">Delete Testimonial</button></form></div>@endforeach</div></div></div></div></body></html>